<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Что такое Книга регистрации казначейских счетов?", "acceptedAnswer": {"@type": "Answer", "text": "Это официальный реестр, который ведёт территориальный орган Федерального казначейства. После внесения записи в Книгу казначейский счёт считается открытым; при изменении номера или закрытии счёта в неё также вносят запись. Порядок установлен приказом Казначейства России от 1 апреля 2020 года № 15н."}}, {"@type": "Question", "name": "Где скачать или посмотреть Книгу регистрации казначейских счетов?", "acceptedAnswer": {"@type": "Answer", "text": "Сама Книга — внутренний документ казначейства, публичного доступа к ней нет. Реквизиты счетов, основанные на её записях, берут из текста контракта, Справочника БИК Банка России и с сайта территориального органа казначейства."}}, {"@type": "Question", "name": "Чем казначейский счёт отличается от единого казначейского счёта?", "acceptedAnswer": {"@type": "Answer", "text": "Единый казначейский счёт (ЕКС) открыт в Банке России на балансовом счёте 40102 и аккумулирует средства бюджетной системы. Казначейские счета на разрядах «03» учитывают конкретные операции. В платёжке ЕКС указывают как счёт банка получателя, а казначейский счёт — как счёт получателя."}}, {"@type": "Question", "name": "Как устроен номер казначейского счёта?", "acceptedAnswer": {"@type": "Answer", "text": "Это 20-значный номер, который начинается с разрядов «03». Следующие разряды кодируют вид счёта: поступления в бюджет (03100), временное распоряжение (03200), средства бюджета и учреждений, средства участников казначейского сопровождения."}}, {"@type": "Question", "name": "Где взять БИК ТОФК для платёжного поручения?", "acceptedAnswer": {"@type": "Answer", "text": "БИК территориального органа казначейства указывается в реквизитах контракта и в официальном Справочнике БИК Банка России. Его сверяют на дату платежа, поскольку при реорганизации органов БИК и счета могут меняться."}}, {"@type": "Question", "name": "Почему платёж на казначейский счёт может вернуться?", "acceptedAnswer": {"@type": "Answer", "text": "Чаще всего из-за устаревших реквизитов (изменился БИК или номер счёта), перепутанных полей (ЕКС и казначейский счёт), отсутствия ИГК или аналитических кодов в назначении платежа для целевых средств."}}, {"@type": "Question", "name": "Это то же самое, что справочник казначейских счетов?", "acceptedAnswer": {"@type": "Answer", "text": "Не совсем. Книга регистрации — внутренний реестр казначейства о факте открытия счетов. Для проверки реквизитов используют публичный Справочник БИК Банка России и реквизиты из контракта."}}, {"@type": "Question", "name": "Когда казначейский счёт считается открытым?", "acceptedAnswer": {"@type": "Answer", "text": "С даты внесения записи в Книгу регистрации казначейских счетов территориальным органом казначейства, а не с момента подачи документов на открытие."}}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "HowTo", "name": "Как найти реквизиты казначейского счёта для платёжного поручения", "inLanguage": "ru-RU", "step": [{"@type": "HowToStep", "position": 1, "name": "Взять реквизиты из контракта", "text": "Найти в контракте банк получателя (ТОФК), БИК, счёт банка (единый казначейский счёт на 40102) и казначейский счёт получателя на 03."}, {"@type": "HowToStep", "position": 2, "name": "Сверить БИК и ЕКС по Справочнику БИК", "text": "Проверить, что банковский идентификационный код ТОФК и счёт 40102 действуют на дату платежа, по официальному Справочнику БИК Банка России."}, {"@type": "HowToStep", "position": 3, "name": "Проверить казначейский счёт получателя", "text": "Убедиться, что номер счёта на 03 соответствует назначению платежа и виду средств."}, {"@type": "HowToStep", "position": 4, "name": "Заполнить назначение платежа", "text": "Для целевых средств указать идентификатор государственного контракта и аналитические коды, требуемые казначейством."}, {"@type": "HowToStep", "position": 5, "name": "Сохранить подтверждение реквизитов", "text": "Зафиксировать источник реквизитов на случай разбора, если платёж задержится или вернётся."}]}
</script>
